import { useEffect, useMemo, useState } from 'react';
import {
  JxChip,
  JxCircularProgress,
  JxBadge,
  JxPagination,
  JxEmptyState,
  JxButton,
} from '@jinx-ui/react';

type Status = 'ok' | 'warning' | 'exceeded';

interface Project {
  id: string;
  name: string;
  status: Status;
  quota: number;
}

const ALL_STATUSES: Status[] = ['ok', 'warning', 'exceeded'];

const STATUS_META: Record<Status, { label: string; tone: 'success' | 'warning' | 'danger' }> = {
  ok: { label: 'В норме', tone: 'success' },
  warning: { label: 'Близко к лимиту', tone: 'warning' },
  exceeded: { label: 'Квота превышена', tone: 'danger' },
};

const PROJECTS: Project[] = [
  { id: 'p1', name: 'Atlas Redesign', status: 'ok', quota: 42 },
  { id: 'p2', name: 'Nebula API', status: 'warning', quota: 78 },
  { id: 'p3', name: 'Comet Billing', status: 'exceeded', quota: 104 },
  { id: 'p4', name: 'Orion Mobile', status: 'ok', quota: 31 },
  { id: 'p5', name: 'Vega Analytics', status: 'warning', quota: 85 },
  { id: 'p6', name: 'Lyra Docs', status: 'ok', quota: 12 },
  { id: 'p7', name: 'Draco Infra', status: 'exceeded', quota: 118 },
  { id: 'p8', name: 'Phoenix CRM', status: 'ok', quota: 55 },
  { id: 'p9', name: 'Hydra Search', status: 'warning', quota: 91 },
  { id: 'p10', name: 'Taurus Payments', status: 'exceeded', quota: 132 },
  { id: 'p11', name: 'Cygnus Support', status: 'ok', quota: 27 },
  { id: 'p12', name: 'Pegasus Growth', status: 'warning', quota: 69 },
];

const PAGE_SIZE = 5;

export default function ProjectSpendPanel() {
  const [activeStatuses, setActiveStatuses] = useState<Set<Status>>(new Set(ALL_STATUSES));
  const [page, setPage] = useState(1);

  const filtered = useMemo(
    () => PROJECTS.filter((p) => activeStatuses.has(p.status)),
    [activeStatuses],
  );

  const pageCount = Math.max(1, Math.ceil(filtered.length / PAGE_SIZE));

  useEffect(() => {
    if (page > pageCount) setPage(pageCount);
  }, [pageCount, page]);

  const pageItems = filtered.slice((page - 1) * PAGE_SIZE, page * PAGE_SIZE);

  const handleRemoveFilter = (status: Status) => {
    setActiveStatuses((prev) => {
      const next = new Set(prev);
      next.delete(status);
      return next;
    });
    setPage(1);
  };

  const handleResetFilters = () => {
    setActiveStatuses(new Set(ALL_STATUSES));
    setPage(1);
  };

  return (
    <div style={{ display: 'flex', flexDirection: 'column', gap: 'var(--jx-space-4)' }}>
      <h2 style={{ margin: 0, font: 'var(--jx-font-heading-md)' }}>Расход по проектам</h2>

      {activeStatuses.size > 0 && (
        <div style={{ display: 'flex', flexWrap: 'wrap', gap: 'var(--jx-space-2)' }}>
          {ALL_STATUSES.filter((status) => activeStatuses.has(status)).map((status) => (
            <JxChip
              key={status}
              tone={STATUS_META[status].tone}
              onRemove={() => handleRemoveFilter(status)}
            >
              {STATUS_META[status].label}
            </JxChip>
          ))}
        </div>
      )}

      {pageItems.length > 0 ? (
        <>
          <div style={{ display: 'flex', flexDirection: 'column', gap: 'var(--jx-space-2)' }}>
            {pageItems.map((project) => (
              <div
                key={project.id}
                style={{
                  display: 'flex',
                  alignItems: 'center',
                  justifyContent: 'space-between',
                  gap: 'var(--jx-space-4)',
                  padding: 'var(--jx-space-3) var(--jx-space-4)',
                  border: '1px solid var(--jx-border-default)',
                  borderRadius: 'var(--jx-radius-md)',
                }}
              >
                <span style={{ fontWeight: 'var(--jx-font-weight-medium)' }}>{project.name}</span>
                <div style={{ display: 'flex', alignItems: 'center', gap: 'var(--jx-space-3)' }}>
                  <JxCircularProgress
                    value={Math.min(project.quota, 100)}
                    size="sm"
                    tone={STATUS_META[project.status].tone}
                    label={`${project.quota}%`}
                  />
                  <JxBadge tone={STATUS_META[project.status].tone}>
                    {STATUS_META[project.status].label}
                  </JxBadge>
                </div>
              </div>
            ))}
          </div>

          {pageCount > 1 && (
            <div style={{ display: 'flex', justifyContent: 'center' }}>
              <JxPagination page={page} pageCount={pageCount} onPageChange={setPage} />
            </div>
          )}
        </>
      ) : (
        <JxEmptyState
          title="Нет проектов по выбранным фильтрам"
          description="Все фильтры сняты или ни один проект им не соответствует."
          action={
            <JxButton variant="primary" onClick={handleResetFilters}>
              Сбросить фильтры
            </JxButton>
          }
        />
      )}
    </div>
  );
}

